const payload = {
  "name": "Research assistant",
  "model": {
    "id": "gpt-5.5"
  },
  "system": "Research the request and cite the sources you use.",
  "description": "A research agent for account questions.",
  "metadata": {
    "team": "support"
  }
};

const response = await fetch("https://managed-agents.votrixai.com/v1/agents", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    "x-api-key": process.env.VOTRIX_API_KEY,
    "votrix-managed-agents-beta": "votrix-managed-agents-2026-04-01"
  },
  body: JSON.stringify(payload)
});

if (!response.ok) throw new Error(await response.text());
console.log(await response.json());

